server {
    listen 443 ssl;
    server_name tickets.example.com;

    # Start with report-only; switch to Content-Security-Policy once clean
    add_header Content-Security-Policy-Report-Only
        "default-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; report-uri /csp-report" always;
    add_header X-Content-Type-Options "nosniff" always;

    location /csp-report {
        # Accept violation reports and keep them for review
        access_log /var/log/nginx/csp-reports.log;
        return 204;
    }
}

